      ctx.fillStyle = '#f5e6c8'; ctx.beginPath(); ctx.arc(cx + r * 1.05, cy + r * 0.8, r * 0.22, 0, Math.PI * 2); ctx.fill(); break; }
    case 'telur': { // fried egg: white + yolk
