      ctx.fillStyle = ing.color; ctx.beginPath(); ctx.moveTo(cx - r * 0.5, cy - r * 0.35); ctx.lineTo(cx + r * 0.5, cy - r * 0.35); ctx.lineTo(cx + r * 0.36, cy + r * 0.65); ctx.lineTo(cx - r * 0.36, cy + r * 0.65); ctx.closePath(); ctx.fill();
